     1→import { useState, useEffect, useRef, type FormEvent } from 'react';
     2→import { apiFetch, getOrCreateOperator } from '../services/api';
     3→import CallsignInput, { type CallsignInputRef } from './CallsignInput';
     4→
     5→const BUNDESLAND_NAMES: Record<string, string> = {
     6→  '01': 'OE1 Wien',
     7→  '02': 'OE2 Salzburg',
     8→  '03': 'OE3 Niederösterreich',
     9→  '04': 'OE4 Burgenland',
    10→  '05': 'OE5 Oberösterreich',
    11→  '06': 'OE6 Steiermark',
    12→  '07': 'OE7 Tirol',
    13→  '08': 'OE8 Kärnten',
    14→  '09': 'OE9 Vorarlberg',
    15→  '10': 'Slowenien',
    16→};
    17→
    18→interface Props {
    19→  exerciseId: string;
    20→  repeaters: any[];
    21→  reports: any[];
    22→  simplexBezirke?: boolean;
    23→  simplexBlCodes?: string;
    24→  onReportCreated: (report: any) => void;
    25→  onReportUpdated: (report: any) => void;
    26→  onReportDeleted: (reportId: number) => void;
    27→}
    28→
    29→interface EntryForm {
    30→  callsign: string;
    31→  operator: any;
    32→  rapport: string;
    33→  notes: string;
    34→  opName: string;
    35→  opQth: string;
    36→  bezirkCode: string;
    37→}
    38→
    39→export default function LandMode({ exerciseId, repeaters, reports, simplexBezirke, simplexBlCodes, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
    40→  const [collapsedReps, setCollapsedReps] = useState<Set<number>>(new Set());
    41→  const [opCallsigns, setOpCallsigns] = useState<Record<number, string>>({});
    42→  const [bezirke, setBezirke] = useState<any[]>([]);
    43→  const [editingId, setEditingId] = useState<number | null>(null);
    44→  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '', opName: '', opQth: '', bezirkCode: '' });
    45→  const [dragReportId, setDragReportId] = useState<number | null>(null);
    46→
    47→  // Load bezirke + OP callsigns
    48→  useEffect(() => {
    49→    Promise.all([
    50→      apiFetch('/api/v1/reference/bezirke'),
    51→      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    52→    ]).then(([bz, exReps]) => {
    53→      setBezirke(bz);
    54→      const ops: Record<number, string> = {};
    55→      for (const er of exReps) {
    56→        if (er.operator_callsign) {
    57→          ops[er.repeater_id] = er.operator_callsign;
    58→        }
    59→      }
    60→      setOpCallsigns(ops);
    61→    }).catch(() => {});
    62→  }, [exerciseId]);
    63→
    64→  // Group repeaters by Bundesland — exclude linked repeaters (those belong to BundMode)
    65→  const repeatersByBl: Record<string, any[]> = {};
    66→  const simplexRepeaters: any[] = [];
    67→  for (const r of repeaters) {
    68→    if (r.is_linked) continue;
    69→    if (r.type === 'simplex') {
    70→      simplexRepeaters.push(r);
    71→    } else {
    72→      const blCode = r.bundesland_code || '_other';
    73→      if (!repeatersByBl[blCode]) repeatersByBl[blCode] = [];
    74→      repeatersByBl[blCode].push(r);
    75→    }
    76→  }
    77→
    78→  const activeBlCodes = simplexBlCodes ? simplexBlCodes.split(',').filter(Boolean) : ['01', '02', '03', '04', '05', '06', '07', '08', '09'];
    79→
    80→  const sortedBlCodes = Object.keys(repeatersByBl).sort((a, b) => {
    81→    if (a === '_other') return 1;
    82→    if (b === '_other') return -1;
    83→    return a.localeCompare(b);
    84→  });
    85→
    86→  const toggleRepeater = (repId: number) => {
    87→    setCollapsedReps(prev => {
    88→      const next = new Set(prev);
    89→      if (next.has(repId)) next.delete(repId); else next.add(repId);
    90→      return next;
    91→    });
    92→  };
    93→
    94→  const saveOpCallsign = async (repeaterId: number, val: string) => {
    95→    try {
    96→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
    97→        method: 'POST',
    98→        body: JSON.stringify({ repeater_id: repeaterId, operator_callsign: val || null }),
    99→      });
   100→    } catch {
   101→      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repeaterId}`, {
   102→        method: 'PATCH',
   103→        body: JSON.stringify({ operator_callsign: val || null }),
   104→      });
   105→    }
   106→  };
   107→
   108→  const parseRapport = (raw: string) => {
   109→    const match = raw.match(/^(\d)\/(\d)(.*)$/);
   110→    if (!match) return { readability: null, strength: null, db_over_s9: null };
   111→    return {
   112→      readability: parseInt(match[1]),
   113→      strength: parseInt(match[2]),
   114→      db_over_s9: match[3]?.trim() || null,
   115→    };
   116→  };
   117→
   118→  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
   119→    try {
   120→      const operator = await getOrCreateOperator(form.callsign, form.operator);
   121→      if (!operator) return;
   122→
   123→      const parsed = parseRapport(form.rapport);
   124→
   125→      try {
   126→        const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
   127→          method: 'POST',
   128→          body: JSON.stringify({
   129→            operator_id: operator.id,
   130→            repeater_id: repeaterId,
   131→            ...parsed,
   132→            notes: form.notes || null,
   133→            bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null,
   134→          }),
   135→        });
   136→        onReportCreated(report);
   137→      } catch (err: any) {
   138→        if (err.message?.includes('existiert')) {
   139→          const existing = reports.find(r => r.operator_id === operator.id && r.repeater_id === repeaterId);
   140→          if (existing) {
   141→            const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${existing.id}`, {
   142→              method: 'PATCH',
   143→              body: JSON.stringify({ ...parsed, notes: form.notes || null }),
   144→            });
   145→            onReportUpdated(updated);
   146→          }
   147→        }
   148→      }
   149→    } catch {}
   150→  };
   151→
   152→  const handleEdit = (report: any) => {
   153→    setEditingId(report.id);
   154→    setEditForm({
   155→      callsign: report.callsign,
   156→      operator: { id: report.operator_id, callsign: report.callsign, name: report.operator_name || null, qth: report.operator_qth || null },
   157→      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
   158→      notes: report.notes || '',
   159→      opName: report.operator_name || '',
   160→      opQth: report.operator_qth || '',
   161→      bezirkCode: report.bezirk_code || '',
   162→    });
   163→  };
   164→
   165→  const handleUpdate = async () => {
   166→    if (!editingId) return;
   167→    const parsed = parseRapport(editForm.rapport);
   168→    try {
   169→      // Save operator name/qth if changed
   170→      if (editForm.operator?.id) {
   171→        const nameChanged = (editForm.opName || '') !== (editForm.operator.name || '');
   172→        const qthChanged = (editForm.opQth || '') !== (editForm.operator.qth || '');
   173→        if (nameChanged || qthChanged) {
   174→          const patch: any = {};
   175→          if (nameChanged) patch.name = editForm.opName || null;
   176→          if (qthChanged) patch.qth = editForm.opQth || null;
   177→          await apiFetch(`/api/v1/operators/${editForm.operator.id}`, {
   178→            method: 'PATCH',
   179→            body: JSON.stringify(patch),
   180→          });
   181→        }
   182→      }
   183→      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
   184→        method: 'PATCH',
   185→        body: JSON.stringify({ ...parsed, notes: editForm.notes || null, bezirk_code: editForm.bezirkCode || null }),
   186→      });
   187→      // Update the returned report with new name/qth so display refreshes
   188→      if (editForm.opName !== undefined) updated.operator_name = editForm.opName || null;
   189→      if (editForm.opQth !== undefined) updated.operator_qth = editForm.opQth || null;
   190→      onReportUpdated(updated);
   191→      setEditingId(null);
   192→    } catch {}
   193→  };
   194→
   195→  const handleMoveToBezirk = async (reportId: number, newBezirkCode: string | null) => {
   196→    try {
   197→      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, {
   198→        method: 'PATCH',
   199→        body: JSON.stringify({ bezirk_code: newBezirkCode }),
   200→      });
   201→      onReportUpdated(updated);
   202→    } catch {}
   203→  };
   204→
   205→  const handleDelete = async (reportId: number) => {
   206→    if (!confirm('Rapport löschen?')) return;
   207→    try {
   208→      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
   209→      onReportDeleted(reportId);
   210→    } catch {}
   211→  };
   212→
   213→  const renderRepeaterCard = (rep: any) => {
   214→    const repReports = reports.filter(r => r.repeater_id === rep.repeater_id && !r.is_op_marker);
   215→    const reportCount = repReports.filter(r => r.readability).length;
   216→    const isCollapsed = collapsedReps.has(rep.repeater_id);
   217→    const isSimplexGrouped = simplexBezirke && rep.type === 'simplex';
   218→    const repBezirke = isSimplexGrouped
   219→      ? bezirke.filter(b => activeBlCodes.includes(b.bundesland_code))
   220→      : bezirke.filter(b => b.bundesland_code === rep.bundesland_code);
   221→
   222→    // Group bezirke by BL for simplex grouped rendering
   223→    const bezirkeByBl: Record<string, any[]> = {};
   224→    if (isSimplexGrouped) {
   225→      for (const bz of repBezirke) {
   226→        if (!bezirkeByBl[bz.bundesland_code]) bezirkeByBl[bz.bundesland_code] = [];
   227→        bezirkeByBl[bz.bundesland_code].push(bz);
   228→      }
   229→    }
   230→
   231→    return (
   232→      <div key={rep.repeater_id} className="bg-white rounded-lg shadow-sm">
   233→        <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
   234→          <div
   235→            onClick={() => toggleRepeater(rep.repeater_id)}
   236→            className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
   237→          >
   238→            <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
   239→            <span className="font-medium text-xs sm:text-sm truncate">{rep.short_name}{rep.repeater_callsign ? ` (${rep.repeater_callsign})` : ''}</span>
   240→            <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
   241→            {rep.frequency_mhz && (
   242→              <span className="text-xs text-gray-400 hidden sm:inline">{rep.frequency_mhz} MHz</span>
   243→            )}
   244→            {rep.offset_mhz && (
   245→              <span className="text-xs text-gray-400 hidden md:inline">({rep.offset_mhz > 0 ? '+' : ''}{rep.offset_mhz})</span>
   246→            )}
   247→            {rep.ctcss_hz && (
   248→              <span className="text-xs text-gray-400 hidden md:inline">CTCSS {rep.ctcss_hz}</span>
   249→            )}
   250→          </div>
   251→          <div className="flex items-center gap-1.5" onClick={e => e.stopPropagation()}>
   252→            <label className={`text-xs ${opCallsigns[rep.repeater_id] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
   253→            <input
   254→              type="text"
   255→              value={opCallsigns[rep.repeater_id] || ''}
   256→              onChange={e => setOpCallsigns(prev => ({ ...prev, [rep.repeater_id]: e.target.value.toUpperCase() }))}
   257→              onBlur={e => saveOpCallsign(rep.repeater_id, e.target.value.toUpperCase())}
   258→              placeholder="Rufz."
   259→              className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${opCallsigns[rep.repeater_id] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
   260→            />
   261→          </div>
   262→        </div>
   263→
   264→        {!isCollapsed && (
   265→          <div className="divide-y divide-gray-100">
   266→            {repBezirke.length > 0 ? (
   267→              <>
   268→                {isSimplexGrouped ? (
   269→                  /* Simplex grouped by BL → Bezirk */
   270→                  <>
   271→                    {activeBlCodes.sort().map(blCode => {
   272→                      const blBezirke = bezirkeByBl[blCode] || [];
   273→                      if (blBezirke.length === 0) return null;
   274→                      const blLabel = BUNDESLAND_NAMES[blCode] || blCode;
   275→                      return (
   276→                        <div key={blCode}>
   277→                          <div className="bg-gray-100 px-2 sm:px-3 py-1">
   278→                            <span className="text-xs font-semibold text-gray-600 uppercase tracking-wide">{blLabel}</span>
   279→                          </div>
   280→                          {blBezirke.map(bz => {
   281→                            const bzReports = repReports.filter(r => r.bezirk_code === bz.code);
   282→                            return (
   283→                              <BezirkRow
   284→                                key={bz.code}
   285→                                bezirk={bz}
   286→                                reports={bzReports}
   287→                                repeaterId={rep.repeater_id}
   288→                                availableBezirke={repBezirke}
   289→                                onSubmit={(form) => handleBezirkSubmit(bz.code, rep.repeater_id, form)}
   290→                                onEdit={handleEdit}
   291→                                onDelete={handleDelete}
   292→                                onMoveToBezirk={handleMoveToBezirk}
   293→                                editingId={editingId}
   294→                                editForm={editForm}
   295→                                onEditChange={setEditForm}
   296→                                onEditSave={handleUpdate}
   297→                                onEditCancel={() => setEditingId(null)}
   298→                                dragReportId={dragReportId}
   299→                                onDragStart={setDragReportId}
   300→                                onDragEnd={() => setDragReportId(null)}
   301→                              />
   302→                            );
   303→                          })}
   304→                        </div>
   305→                      );
   306→                    })}
   307→                    {/* Sonstige — reports without matching bezirk */}
   308→                    {(() => {
   309→                      const bzCodes = new Set(repBezirke.map(b => b.code));
   310→                      const unassigned = repReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
   311→                      return (
   312→                        <BezirkRow
   313→                          bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
   314→                          reports={unassigned}
   315→                          repeaterId={rep.repeater_id}
   316→                          availableBezirke={repBezirke}
   317→                          onSubmit={(form) => handleBezirkSubmit('??', rep.repeater_id, form)}
   318→                          onEdit={handleEdit}
   319→                          onDelete={handleDelete}
   320→                          onMoveToBezirk={handleMoveToBezirk}
   321→                          editingId={editingId}
   322→                          editForm={editForm}
   323→                          onEditChange={setEditForm}
   324→                          onEditSave={handleUpdate}
   325→                          onEditCancel={() => setEditingId(null)}
   326→                          dragReportId={dragReportId}
   327→                          onDragStart={setDragReportId}
   328→                          onDragEnd={() => setDragReportId(null)}
   329→                        />
   330→                      );
   331→                    })()}
   332→                  </>
   333→                ) : (
   334→                  /* Normal repeater with bezirke */
   335→                  <>
   336→                    {repBezirke.map(bz => {
   337→                      const bzReports = repReports.filter(r => r.bezirk_code === bz.code);
   338→                      return (
   339→                        <BezirkRow
   340→                          key={bz.code}
   341→                          bezirk={bz}
   342→                          reports={bzReports}
   343→                          repeaterId={rep.repeater_id}
   344→                          availableBezirke={repBezirke}
   345→                          onSubmit={(form) => handleBezirkSubmit(bz.code, rep.repeater_id, form)}
   346→                          onEdit={handleEdit}
   347→                          onDelete={handleDelete}
   348→                          onMoveToBezirk={handleMoveToBezirk}
   349→                          editingId={editingId}
   350→                          editForm={editForm}
   351→                          onEditChange={setEditForm}
   352→                          onEditSave={handleUpdate}
   353→                          onEditCancel={() => setEditingId(null)}
   354→                          dragReportId={dragReportId}
   355→                          onDragStart={setDragReportId}
   356→                          onDragEnd={() => setDragReportId(null)}
   357→                        />
   358→                      );
   359→                    })}
   360→                    {/* Sonstige — reports without matching bezirk + entry form */}
   361→                    {(() => {
   362→                      const bzCodes = new Set(repBezirke.map(b => b.code));
   363→                      const unassigned = repReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
   364→                      return (
   365→                        <BezirkRow
   366→                          bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
