     9→interface Stats {
    10→  totalParticipants: number;
    11→  totalReports: number;
    12→  perRepeater: { short_name: string; count: number }[];
    13→}
    14→
    15→export default function ExercisePage() {
    16→  const { id } = useParams<{ id: string }>();
    17→  const [exercise, setExercise] = useState<any>(null);
    18→  const [mode, setMode] = useState<'land' | 'bund'>('land');
    19→  const oeLinkEnabled = exercise?.oe_link_enabled !== 0;
    20→  const [stats, setStats] = useState<Stats>({ totalParticipants: 0, totalReports: 0, perRepeater: [] });
    21→  const [reports, setReports] = useState<any[]>([]);
    22→  const [loading, setLoading] = useState(true);
    23→  const [organisator, setOrganisator] = useState('');
    24→  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
    25→  const savedTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    26→  const socketRef = useRef(getSocket());
    27→
    28→  const refreshStats = useCallback(async () => {
    29→    if (!id) return;
    30→    try {
    31→      const s = await apiFetch(`/api/v1/exercises/${id}/stats`);
    32→      setStats(s);
    33→    } catch {}
    34→  }, [id]);
    35→
    36→  useEffect(() => {
    37→    if (!id) return;
    38→    setLoading(true);
    39→    apiFetch(`/api/v1/exercises/${id}`)
    40→      .then(data => {
    41→        setExercise(data);
    42→        setReports(data.reports || []);
    43→        if (data.organisator) setOrganisator(data.organisator);
    44→      })
    45→      .catch(() => {})
    46→      .finally(() => setLoading(false));
    47→    refreshStats();
    48→  }, [id, refreshStats]);
    49→
    50→  useEffect(() => {
    51→    if (!id) return;
    52→    const socket = socketRef.current;
    53→    socket.emit('join_exercise', { exercise_id: id });
    54→
    55→    socket.on('report_created', (data: any) => {
    56→      setReports(prev => [data, ...prev]);
    57→      refreshStats();
    58→    });
    59→    socket.on('report_updated', (data: any) => {
    60→      setReports(prev => prev.map(r => r.id === data.id ? data : r));
    61→      refreshStats();
    62→    });
    63→    socket.on('report_deleted', (data: any) => {
    64→      setReports(prev => prev.filter(r => r.id !== data.report_id));
    65→      refreshStats();
    66→    });
    67→
    68→    return () => {
    69→      socket.emit('leave_exercise', { exercise_id: id });
    70→      socket.off('report_created');
    71→      socket.off('report_updated');
    72→      socket.off('report_deleted');
    73→    };
    74→  }, [id, refreshStats]);
    75→
    76→  const handleReportCreated = useCallback((report: any) => {
    77→    setReports(prev => [report, ...prev]);
    78→    socketRef.current.emit('report_created', { ...report, exercise_id: id! });
    79→    refreshStats();
    80→  }, [id, refreshStats]);
    81→
    82→  const handleReportUpdated = useCallback((report: any) => {
    83→    setReports(prev => prev.map(r => r.id === report.id ? report : r));
    84→    socketRef.current.emit('report_updated', { ...report, exercise_id: id! });
    85→    refreshStats();
    86→  }, [id, refreshStats]);
    87→
    88→  const handleReportDeleted = useCallback((reportId: number) => {
    89→    setReports(prev => prev.filter(r => r.id !== reportId));
    90→    socketRef.current.emit('report_deleted', { report_id: reportId, exercise_id: id! });
    91→    refreshStats();
    92→  }, [id, refreshStats]);
    93→
    94→  const updateOrganisator = async (val: string) => {
    95→    setSaveStatus('saving');
    96→    if (savedTimerRef.current) clearTimeout(savedTimerRef.current);
    97→    try {
    98→      await apiFetch(`/api/v1/exercises/${id}`, {
    99→        method: 'PATCH',
   100→        body: JSON.stringify({ organisator: val || null }),
   101→      });
   102→      setExercise((prev: any) => prev ? { ...prev, organisator: val || null } : null);
   103→      setSaveStatus('saved');
   104→      savedTimerRef.current = setTimeout(() => setSaveStatus('idle'), 2000);
   105→    } catch {
   106→      setSaveStatus('idle');
   107→    }
   108→  };
   109→
   110→  if (loading) return <p className="text-gray-500 p-4">Laden...</p>;
   111→  if (!exercise) return <p className="text-red-500 p-4">Übung nicht gefunden</p>;
   112→
   113→  return (
   114→    <div className="space-y-4">
   115→      <div className="flex items-center justify-between flex-wrap gap-2">
   116→        <h1 className="text-base sm:text-xl font-bold text-[#1e3a5f] min-w-0">
   117→          <span className="block sm:inline">{exercise.name || 'Übung'}</span>
   118→          <span className="hidden sm:inline"> — </span>
   119→          <span className="block sm:inline text-sm sm:text-xl">{new Date(exercise.date + 'T00:00:00').toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit', year: 'numeric' })}</span>
   120→        </h1>
   121→        <div className="flex items-center gap-2 flex-wrap">
   122→          <div className="flex items-center gap-1.5">
   123→            <label className={`text-xs ${organisator ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>Organisator:</label>
   124→            <input
   125→              type="text"
   126→              value={organisator}
   127→              onChange={e => setOrganisator(e.target.value.toUpperCase())}
   128→              onBlur={e => updateOrganisator(e.target.value.toUpperCase())}
   129→              placeholder="Rufzeichen"
   130→              className={`border rounded px-2 py-1 text-sm font-mono uppercase w-24 sm:w-28 focus:outline-none focus:ring-2 focus:ring-blue-500 ${organisator ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
   131→            />
   132→            {saveStatus === 'saving' && <span className="text-xs text-amber-600 animate-pulse">Speichern...</span>}
   133→            {saveStatus === 'saved' && <span className="text-xs text-green-600">Gespeichert</span>}
   134→          </div>
   135→          <Link to={`/exercises/${id}/setup`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-2 sm:px-3 py-1 rounded text-xs sm:text-sm">
   136→            Einrichten
   137→          </Link>
   138→          <Link to={`/exercises/${id}/reports`} className="bg-red-100 hover:bg-red-200 text-red-800 px-2 sm:px-3 py-1 rounded text-xs sm:text-sm">
   139→            Auswertung
   140→          </Link>
   141→        </div>
   142→      </div>
   143→
   144→      <RunningTotals stats={stats} />
   145→
   146→      {oeLinkEnabled && (
   147→        <div className="flex gap-1 bg-white rounded-lg p-1 shadow-sm w-full sm:w-fit">
   148→          <button
   149→            onClick={() => setMode('land')}
   150→            className={`flex-1 sm:flex-none px-3 sm:px-4 py-1.5 rounded text-xs sm:text-sm font-medium ${mode === 'land' ? 'bg-[#1e3a5f] text-white' : 'text-gray-600 hover:bg-gray-100'}`}
   151→          >
   152→            Frequenzen
   153→          </button>
   154→          <button
   155→            onClick={() => setMode('bund')}
   156→            className={`flex-1 sm:flex-none px-3 sm:px-4 py-1.5 rounded text-xs sm:text-sm font-medium ${mode === 'bund' ? 'bg-[#1e3a5f] text-white' : 'text-gray-600 hover:bg-gray-100'}`}
   157→          >
   158→            OE-Link
   159→          </button>
   160→        </div>
   161→      )}
   162→
   163→      {mode === 'land' || !oeLinkEnabled ? (
   164→        <LandMode
   165→          exerciseId={id!}
   166→          repeaters={exercise.repeaters || []}
   167→          reports={reports}
   168→          simplexBezirke={!!exercise.simplex_bezirke}
   169→          simplexBlCodes={exercise.simplex_bl_codes || ''}
   170→          onReportCreated={handleReportCreated}
   171→          onReportUpdated={handleReportUpdated}
   172→          onReportDeleted={handleReportDeleted}
   173→        />
   174→      ) : (
