   526→
   527→      <form onSubmit={handleSubmit} className="flex items-center gap-1">
   528→        {linkedRepeaters.length > 0 && (
   529→          <select
   530→            value={repeaterId || ''}
   531→            onChange={e => setRepeaterId(parseInt(e.target.value))}
   532→            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
   533→          >
   534→            {linkedRepeaters.map(r => (
   535→              <option key={r.id} value={r.id}>
   536→                {r.site_name || r.short_name}{r.callsign ? ` (${r.callsign})` : ''}
   537→              </option>
   538→            ))}
   539→          </select>
   540→        )}
   541→        <CallsignInput
   542→          ref={callsignRef}
   543→          value={form.callsign}
   544→          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
